/bin/zsh -lc "cat > tb.sv <<'EOF'
module tb;
  reg clk = 0;
  reg rst_n = 0;
  wire [3:0] gray_out;
  TopModule dut(.clk(clk), .rst_n(rst_n), .gray_out(gray_out));
  always #5 clk = ~clk;
  integer i;
  initial begin
    "'$display("time clk rst gray");
    $monitor("%0t %0b %0b %04b", $time, clk, rst_n, gray_out);
    #12 rst_n = 1;
    for (i = 0; i < 12; i = i + 1) begin
      @(posedge clk);
      #1;
      $display("sample %0d gray=%04b", i, gray_out);
    end
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

