/bin/zsh -lc "cat > tb_check.sv <<'EOF'
module tb;
  reg clk = 0;
  reg rst_n = 0;
  wire [3:0] gray_out;
  TopModule dut(.clk(clk), .rst_n(rst_n), .gray_out(gray_out));
  always #5 clk = ~clk;

  reg [3:0] expected [0:15];
  integer i;
  initial begin
    expected[0]=4'h0; expected[1]=4'h1; expected[2]=4'h3; expected[3]=4'h2;
    expected[4]=4'h6; expected[5]=4'h7; expected[6]=4'h5; expected[7]=4'h4;
    expected[8]=4'hc; expected[9]=4'hd; expected[10]=4'hf; expected[11]=4'he;
    expected[12]=4'ha; expected[13]=4'hb; expected[14]=4'h9; expected[15]=4'h8;

    #12 rst_n = 1;
    @(posedge clk); #1;
    if (gray_out "'!== expected[0]) begin $display("FAIL reset release expected %04b got %04b", expected[0], gray_out); $finish(1); end
    for (i = 1; i < 16; i = i + 1) begin
      repeat (2) @(posedge clk);
      #1;
      if (gray_out !== expected[i]) begin
        $display("FAIL step %0d expected %04b got %04b", i, expected[i], gray_out);
        $finish(1);
      end
    end
    $display("PASS");
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv_check TopModule.sv tb_check.sv && vvp simv_check'

