item.aggregated_output:
 1	module TopModule(
 2	   input   clk,
 3	   input   rst_n,
 4	
 5	   output  reg [3:0] gray_out
 6	);
 7	//Gray code to binary conversion
 8	reg  [3:0] bin_out;
 9	wire [3:0] gray_wire;
10	
11	always @(posedge clk or negedge rst_n)begin
12	   if(rst_n == 1'b0) begin
13	      bin_out <= 4'b0;
14	   end
15	   else begin
16	      bin_out[3] = gray_wire[3];
17	      bin_out[2] = gray_wire[2]^bin_out[3];
18	      bin_out[1] = gray_wire[1]^bin_out[2];
19	      bin_out[0] = gray_wire[0]^bin_out[1];
20	   end 
21	end
22	//Binary increment
23	reg [3:0] bin_add_wire;
24	always @(posedge clk or negedge rst_n)begin
25	   if(rst_n == 1'b0) begin
26	      bin_add_wire <= 4'b0;
27	   end
28	   else begin
29	      bin_add_wire <= bin_out + 1'b1;
30	   end
31	end
32	//Binary to gray code conversion
33	assign gray_wire = (bin_add_wire >> 1) ^ bin_add_wire;
34	
35	always @(posedge clk or negedge rst_n)begin
36	   if(rst_n == 1'b0) begin
37	      gray_out <= 4'b0;
38	   end
39	   else begin
40	      gray_out <= gray_wire;
41	   end
42	end
43	endmodule
